public int[] TopKFrequentSort(int[] nums, int k)
{
    var counts = new Dictionary<int, int>();
    foreach (int v in nums) counts[v] = counts.GetValueOrDefault(v) + 1;

    return counts
        .OrderByDescending(pair => pair.Value)
        .Take(k)
        .Select(pair => pair.Key)
        .ToArray();
}

public int[] TopKFrequent(int[] nums, int k)
{
    var counts = new Dictionary<int, int>();
    foreach (int v in nums) counts[v] = counts.GetValueOrDefault(v) + 1;

    // buckets[f] holds every value that appears exactly f times
    var buckets = new List<int>[nums.Length + 1];
    for (int i = 0; i < buckets.Length; i++)
    {
        buckets[i] = new List<int>();
    }

    foreach (var (value, frequency) in counts)
    {
        buckets[frequency].Add(value);
    }

    var result = new List<int>(k);
    for (int f = buckets.Length - 1; f >= 1 && result.Count < k; f--)
    {
        foreach (int value in buckets[f])
        {
            result.Add(value);
            if (result.Count == k) break;
        }
    }

    return result.ToArray();
}

public int[] TopKFrequentHeap(int[] nums, int k)
{
    var counts = new Dictionary<int, int>();
    foreach (int v in nums) counts[v] = counts.GetValueOrDefault(v) + 1;

    var heap = new PriorityQueue<int, int>();

    foreach (var (value, frequency) in counts)
    {
        heap.Enqueue(value, frequency);
        if (heap.Count > k) heap.Dequeue();
    }

    var result = new int[k];
    for (int i = 0; i < k; i++) result[i] = heap.Dequeue();
    return result;
}

